<?php
require_auth(['admin']);
$pageTitle = 'Bài nộp UGC';
$filter = (string) ($_GET['status'] ?? '');
$sql = 'SELECT s.*, u.name AS student_name, u.student_code, c.title AS campaign_title, c.reward_points FROM submissions s JOIN users u ON u.id = s.user_id JOIN campaigns c ON c.id = s.campaign_id';
$params = [];
if (in_array($filter, ['pending','approved','rejected'], true)) { $sql .= ' WHERE s.status = ?'; $params[] = $filter; }
$sql .= ' ORDER BY CASE s.status WHEN \'pending\' THEN 0 ELSE 1 END, s.id DESC';
$submissions = rows($sql, $params);
?>
<div class="page-actions"><p class="page-intro">Duyệt nội dung theo brief và cộng điểm minh bạch cho sinh viên.</p><div class="segmented"><a class="<?= $filter === '' ? 'active' : '' ?>" href="index.php?page=admin-submissions">Tất cả</a><a class="<?= $filter === 'pending' ? 'active' : '' ?>" href="index.php?page=admin-submissions&status=pending">Chờ duyệt</a><a class="<?= $filter === 'approved' ? 'active' : '' ?>" href="index.php?page=admin-submissions&status=approved">Đã duyệt</a></div></div>
<section class="panel-card"><div class="table-responsive"><table class="table clean-table align-middle"><thead><tr><th>Sinh viên</th><th>Nội dung</th><th>Chiến dịch</th><th>Thưởng</th><th>Trạng thái</th><th></th></tr></thead><tbody><?php foreach ($submissions as $submission): ?><tr><td><div class="person-cell"><span class="avatar avatar-sm"><?= e(initials($submission['student_name'])) ?></span><div><strong><?= e($submission['student_name']) ?></strong><small><?= e($submission['student_code']) ?></small></div></div></td><td><a class="content-link" href="<?= e($submission['content_url']) ?>" target="_blank" rel="noopener"><i class="bi bi-play-circle-fill"></i><span><?= e($submission['caption'] ?: 'Xem nội dung') ?></span></a></td><td><?= e($submission['campaign_title']) ?></td><td><strong><?= (int) $submission['reward_points'] + (int) $submission['bonus_points'] ?> điểm</strong><small class="d-block text-muted"><?= (int) $submission['bonus_points'] ?> bonus trước hệ số</small></td><td><span class="badge text-bg-<?= e(status_badge($submission['status'])) ?>-subtle"><?= e($submission['status']) ?></span></td><td><?php if ($submission['status'] === 'pending'): ?><button class="btn btn-sm btn-brand" data-bs-toggle="modal" data-bs-target="#review<?= (int) $submission['id'] ?>">Duyệt</button><?php else: ?><small><?= e($submission['feedback']) ?></small><?php endif; ?></td></tr><?php if ($submission['status'] === 'pending'): ?><div class="modal fade" id="review<?= (int) $submission['id'] ?>" tabindex="-1"><div class="modal-dialog modal-dialog-centered"><div class="modal-content"><form method="post" action="actions.php?action=review_submission"><?= csrf_field() ?><input type="hidden" name="submission_id" value="<?= (int) $submission['id'] ?>"><div class="modal-header"><h2 class="modal-title fs-5">Duyệt bài của <?= e($submission['student_name']) ?></h2><button class="btn-close" type="button" data-bs-dismiss="modal" aria-label="Đóng"></button></div><div class="modal-body"><p><strong><?= e($submission['campaign_title']) ?></strong></p><p><?= e($submission['caption']) ?></p><div class="review-metrics"><div><label class="form-label">Lượt xem</label><input class="form-control" type="number" name="views" min="0" value="0"></div><div><label class="form-label">Bình luận</label><input class="form-control" type="number" name="comments" min="0" value="0"></div><div><label class="form-label">Điểm AI</label><input class="form-control" type="number" name="ai_score" min="0" max="100" value="0"></div></div><div class="bonus-rule"><i class="bi bi-stars"></i><span>+40 điểm bonus nếu đạt 10.000 views, 100 bình luận hoặc AI score từ 85.</span></div><label class="form-label">Nhận xét</label><textarea class="form-control" name="feedback" rows="3" placeholder="Nội dung tự nhiên, đúng brief..."></textarea></div><div class="modal-footer"><button class="btn btn-outline-danger" name="status" value="rejected">Yêu cầu sửa</button><button class="btn btn-success" name="status" value="approved">Duyệt và tính thưởng</button></div></form></div></div></div><?php endif; ?><?php endforeach; ?></tbody></table></div></section>
